Route::get('/thanh-toan',[CheckoutController::class,'index'])->name('checkout');Route::post('/thanh-toan/ma-giam-gia',[CheckoutController::class,'applyCoupon'])->name('checkout.coupon');Route::delete('/thanh-toan/ma-giam-gia',[CheckoutController::class,'removeCoupon'])->name('checkout.coupon.remove');Route::post('/thanh-toan',[CheckoutController::class,'place'])->name('checkout.place')->middleware('throttle:10,1');Route::get('/dat-hang-thanh-cong/{order}',[CheckoutController::class,'success'])->name('checkout.success');
