Route::prefix('admin')->name('admin.')->middleware(['auth','admin'])->group(function(){Route::get('/',[AdminController::class,'dashboard'])->name('dashboard');Route::get('/san-pham',[AdminController::class,'products'])->name('products');Route::post('/san-pham',[AdminController::class,'saveProduct'])->name('products.save');Route::delete('/san-pham/{product}',[AdminController::class,'deleteProduct'])->name('products.delete');Route::get('/danh-muc',[AdminController::class,'categories'])->name('categories');Route::post('/danh-muc',[AdminController::class,'saveCategory'])->name('categories.save');Route::delete('/danh-muc/{category}',[AdminController::class,'deleteCategory'])->name('categories.delete');Route::get('/don-hang',[AdminController::class,'orders'])->name('orders');Route::patch('/don-hang/{order}',[AdminController::class,'updateOrder'])->name('orders.update');Route::get('/khach-hang',[AdminController::class,'customers'])->name('customers');Route::get('/ma-giam-gia',[AdminController::class,'coupons'])->name('coupons');Route::post('/ma-giam-gia',[AdminController::class,'saveCoupon'])->name('coupons.save');Route::delete('/ma-giam-gia/{coupon}',[AdminController::class,'deleteCoupon'])->name('coupons.delete');Route::get('/bao-cao',[AdminController::class,'reports'])->name('reports');});
